import { Plugin } from '@ckeditor/ckeditor5-core';
import { ButtonView, ContextualBalloon } from '@ckeditor/ckeditor5-ui';

import {getOPResource, getPluginContext} from '../op-context/op-context';
import imageIcon from './../../icons/attachment-add.svg';

export default class OPMacroWpEdocFilesToolbar extends Plugin {
	static get requires() {
		return [ ContextualBalloon ];
	}

	static get pluginName() {
		return 'OPMacroWpEdocFilesToolbar';
	}

	static get buttonName() {
		return 'OPShowWpEdocFiles';
	}

	init() {
		const editor = this.editor;
		const model = this.editor.model;
		const pluginContext = getPluginContext(editor);

		editor.ui.componentFactory.add( OPMacroWpEdocFilesToolbar.buttonName, locale => {
			const view = new ButtonView( locale );

			view.set( {
				label: window.I18n.t('js.editor.macro.wp_edoc_files.button'),
				icon: imageIcon,
				tooltip: true,
			} );

			// Callback executed once the image is clicked.
			view.on( 'execute', () => {
				const resource = getOPResource(editor);
				const macroService = pluginContext.services.macros;
				macroService
					.configureWpEdocFiles(resource.id)
					.then((result) => editor.model.change(writer => {
						if (!Array.isArray(result) || result.length === 0) throw new Error('文件列表不能为空');
						result.forEach((item) => {
							const link = writer.createText( item.name );

							writer.setAttribute( 'linkHref', item.href, link );

							const selection = editor.model.document.selection;

							const selectedElement = selection.getSelectedElement();

							const isLimit = !!selectedElement && editor.model.schema.isLimit(selectedElement);

							if (isLimit) {
								editor.model.insertContent( link );
							} else {
								const { position } = writer.split(selection.getLastPosition());
								editor.model.insertContent( link, position );
							}
						});
					})
				);
			} );

			return view;
		} );
	}
}
