// This SVG file import will be handled by webpack's raw-text loader.
// This means that imageIcon will hold the source SVG.
import imageIcon from './../../icons/clouds.svg';

import { ButtonView } from '@ckeditor/ckeditor5-ui';

import { Plugin } from '@ckeditor/ckeditor5-core';
import { getOPPath } from '../op-context/op-context';
import { toWidget } from '@ckeditor/ckeditor5-widget';

export default class OPMacroDdsPlugin extends Plugin {

	static get pluginName() {
		return 'OPMacroDdsPlugin';
	}

	static get buttonName() {
		return 'OPShowDds';
	}

	ddsModal = null

	ddsOpts = {
		eventName: 'OPMacroDdsFilesShare',
		uid: Date.now().toString(),
	}

	viewOpts = {
		name: 'div',
		classes: 'op-macro-dds-file',
		className: 'op-macro-dds-file-box',
		dataName: 'macro',
		dataClassName: 'show_dds_file_link',
		outerShareType: 'publish_files',
	}

	handleDdsMessage = (e) => {
		const { uid, data } = e.detail || {};
		if (uid !== this.ddsOpts.uid) return;

		this.closeDdsModal();

		const editor = this.editor;

		data.forEach(item => {
			editor.model.change((writer) => {
				const selection = editor.model.document.selection;

				const elem = writer.createElement(this.viewOpts.classes);

				const data = JSON.stringify(item);

				writer.setAttribute('data-file', data, elem);

				writer.setAttribute('classes', this.viewOpts.classes, elem);

				const selectedElement = selection.getSelectedElement();

				const isLimit = !!selectedElement && editor.model.schema.isLimit(selectedElement);

				if (isLimit) {
					editor.model.insertContent( elem );
				} else {
					const { position } = writer.split(selection.getLastPosition());
					editor.model.insertContent( elem, position );
				}
			});
		});
	};

	init() {
		const editor = this.editor;

		this._defineSchema();
		this._defineConverters();

		window.addEventListener(this.ddsOpts.eventName, this.handleDdsMessage);

		editor.ui.componentFactory.add( OPMacroDdsPlugin.buttonName, locale => {
			const view = new ButtonView( locale );

			view.set( {
				label: window.I18n.t('js.editor.macro.dds.button'),
				icon: imageIcon,
				tooltip: true
			} );

			// Callback executed once the image is clicked.
			view.on( 'execute', () => {
				this.openDdsModal();
			} );

			return view;
		} );
	}

	destroy() {
		this.destroyDdsModal();
		window.removeEventListener(this.ddsOpts.eventName, this.handleDdsMessage);
	}

	_defineSchema() {
		const schema = this.editor.model.schema;
		schema.register( this.viewOpts.classes, {
			allowWhere: ['$block'],
			allowAttributes: [
				'classes',
				'data-file',
			],
			isBlock: true,
		    isLimit: true,
			isObject: true,
		});
	}

	_defineConverters() {
		const conversion = this.editor.conversion;

		conversion.for( 'upcast' )
			.elementToElement( {
				view: {
					name: this.viewOpts.name,
					classes: this.viewOpts.classes,
				},
				model: this.createDdsFileModel,
			} );

		conversion.for( 'upcast' )
			.elementToElement( {
				view: {
					name: this.viewOpts.dataName,
					classes: this.viewOpts.dataClassName,
				},
				model: this.createDdsFileModel,
			} );

		conversion.for('editingDowncast').elementToElement({
			model: this.viewOpts.classes,
			view: (modelElement, { writer }) => {
				return toWidget(this.createDdsFileViewElement(writer, modelElement), writer);
			}
		});

		conversion.for('dataDowncast').elementToElement({
			model: this.viewOpts.classes,
			view: (modelElement, { writer }) => {
				const element = writer.createContainerElement(
					this.viewOpts.dataName,
					{
						'class': [this.viewOpts.dataClassName, this.viewOpts.className].join(' '),
						'data-file': modelElement.getAttribute('data-file') || '',
						'data-classes': this.viewOpts.classes,
					}
				);

				return element;
			}
		});
	}

	createDdsFileModel = (viewElement, { writer }) => {
		const elem = writer.createElement(this.viewOpts.classes);

		writer.setAttribute('classes', this.viewOpts.classes, elem);

		const dataStr = viewElement.getAttribute('data-file');

		writer.setAttribute('data-file', dataStr, elem);

		return elem;
	}

	parseData = (str) => {
		try {
			return JSON.parse(str);
		} catch(err) {
			return {};
		}
	}

	createDdsFileViewElement(writer, modelElement) {
		const dataStr = modelElement.getAttribute('data-file');

		const data = this.parseData(dataStr);

		if (data.type === this.viewOpts.outerShareType) return this.createOuterShareContainer(writer, data, dataStr);

		return this.createInnerShareContainer(writer, data, dataStr);
	}

	createInnerShareContainer(writer, data, dataStr) {
		const container = writer.createContainerElement(this.viewOpts.name);

		writer.setAttribute('classes', this.viewOpts.classes, container);

		writer.setAttribute('data-file', dataStr, container);

		writer.addClass(this.viewOpts.className, container);

		const nameP = writer.createContainerElement('p');

		writer.addClass('dds-link', nameP);

		writer.setAttribute('data-is-folder', !!data.isFolder, nameP);

		const nameText = writer.createText( data.name || '未命名' );

		writer.insert( writer.createPositionAt( nameP, 0 ), nameText );

		writer.insert( writer.createPositionAt( container, 0 ), nameP );

		if (data.parentFolderFullPath) {
			const pathP = writer.createContainerElement('p');

			writer.addClass('dds-description', pathP);

			const pathText = writer.createText( data.parentFolderFullPath );

			writer.insert( writer.createPositionAt( pathP, 0 ), pathText );

			writer.insert( writer.createPositionAt( container, 'end' ), pathP );
		}

		return container;
	}

	createOuterShareContainer(writer, data, dataStr) {
		const container = writer.createContainerElement(this.viewOpts.name);

		writer.setAttribute('classes', this.viewOpts.classes, container);

		writer.setAttribute('data-file', dataStr, container);

		writer.addClass(this.viewOpts.className, container);

		data.files.forEach(file => {
			const fileP = writer.createContainerElement('p');

			writer.addClass('dds-link', fileP);

			writer.setAttribute('data-is-folder', !!file.isFolder, fileP);

			const fileNameText = writer.createText( file.name || '未命名' );

			writer.insert( writer.createPositionAt( fileP, 0 ), fileNameText );

			writer.insert( writer.createPositionAt( container, 'end' ), fileP );
		});

		const titleP = writer.createContainerElement('p');

		writer.addClass('dds-description', titleP);

		const titleText = writer.createText( `外链分享地址：${data.url}，验证码：【${data.pwd || '无'}】，有效期：${data.expiredAt}` );

		writer.insert( writer.createPositionAt( titleP, 0 ), titleText );

		writer.insert( writer.createPositionAt( container, 'end' ), titleP );

		return container;
	}

	createDdsModal(url) {
		if (!url) throw new Error('dds iframe url is empty!');

		// 容器
		const container = document.createElement('div');

		const cStyles = {
			position: 'fixed',
			top: 0,
			bottom: 0,
			left: 0,
			right: 0,
			display: 'flex',
			justifyContent: 'center',
			alignItems: 'center',
			zIndex: 1000,
		};
		Object.keys(cStyles).forEach(key => container.style[key] = cStyles[key]);

		document.body.append(container);

		// 遮罩
		const mask = document.createElement('div');

		const mStyles = {
			position: 'absolute',
			background: 'rgba(0, 0, 0, .5)',
			top: 0,
			bottom: 0,
			left: 0,
			right: 0,
		};
		Object.keys(mStyles).forEach(key => mask.style[key] = mStyles[key]);

		mask.addEventListener('click', () => {
			this.closeDdsModal();
		});

		container.appendChild(mask);

		// wrapper
		const wrapper = document.createElement('div');

		const wStyles = {
			position: 'relative',
			width: '375px',
			height: '667px',
			maxWidth: '100%',
			maxHeight: '100%',
			background: 'white',
			boxShadow: '0 0 8px 0 rgba(0, 0, 0, .5)',
		};
		Object.keys(wStyles).forEach(key => wrapper.style[key] = wStyles[key]);

		container.appendChild(wrapper);

		// iframe
		const iframe = document.createElement('iframe');

		iframe.src = url;

		const iStyles = {
			width: '100%',
			height: '100%',
			maxWidth: '100%',
			maxHeight: '100%',
			border: 'none',
		};
		Object.keys(iStyles).forEach(key => iframe.style[key] = iStyles[key]);

		wrapper.appendChild(iframe);

		// 关闭按钮
		const button = document.createElement('button');

		button.title = '关闭';

		button.innerHTML = `
			<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16">
				<path d="M4.646 4.646a.5.5 0 0 1 .708 0L8 7.293l2.646-2.647a.5.5 0 0 1 .708.708L8.707 8l2.647 2.646a.5.5 0 0 1-.708.708L8 8.707l-2.646 2.647a.5.5 0 0 1-.708-.708L7.293 8 4.646 5.354a.5.5 0 0 1 0-.708z"/>
			</svg>
		`;

		const bStyles = {
			position: 'absolute',
			top: '8px',
			right: '8px',
			width: '24px',
			height: '24px',
			display: 'flex',
			justifyContent: 'center',
			alignItems: 'center',
			color: 'black',
			padding: 0,
			background: 'white',
			boxShadow: '0 0 8px 0 rgba(0, 0, 0, .5)',
			border: 'none',
			borderRadius: '50%',
			outline: 'none',
		};
		Object.keys(bStyles).forEach(key => button.style[key] = bStyles[key]);

		wrapper.appendChild(button);

		button.addEventListener('click', () => {
			this.closeDdsModal();
		});

		this.ddsModal = container;
	}

	destroyDdsModal() {
		if (this.ddsModal) this.ddsModal.remove();
		this.ddsModal = null;
	}

	openDdsModal() {
		if (this.ddsModal) {
			this.ddsModal.style.display = 'flex';
		} else {
			const ddsConfig = this.editor.config.get('openProject.ddsConfig') || {};
			const url = getOPPath(this.editor).ddsPath({
				event_name: this.ddsOpts.eventName,
				uid: this.ddsOpts.uid,
				...ddsConfig,
			});
			this.createDdsModal(url);
		}
	}

	closeDdsModal() {
		if (this.ddsModal) this.ddsModal.style.display = 'none';
	}
}
