import { Plugin } from '@ckeditor/ckeditor5-core';
import { Widget } from '@ckeditor/ckeditor5-widget';
import OPMacroWpEdocFilesToolbar from './op-macro-wp-edoc-files-toolbar';

export default class OPMacroWpEdocFilesPlugin extends Plugin {
	static get requires() {
		return [ Widget, OPMacroWpEdocFilesToolbar ];
	}

	static get pluginName() {
		return 'OPMacroWpEdocFiles';
	}

	static get buttonName() {
		return OPMacroWpEdocFilesToolbar.buttonName;
	}
}
